package ssosql

// PG16 catalog extraction is independent of information_schema role visibility.
const catalogQuery = `SELECT json_build_object('columns',(SELECT json_agg(x ORDER BY table_name,attnum)FROM(SELECT c.relname table_name,a.attnum,a.attname,format_type(a.atttypid,a.atttypmod) type,a.attnotnull not_null,a.attgenerated generated,pg_get_expr(d.adbin,d.adrelid) default_expr FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_attribute a ON a.attrelid=c.oid LEFT JOIN pg_attrdef d ON d.adrelid=c.oid AND d.adnum=a.attnum WHERE n.nspname='ops_sso_v1' AND c.relkind='r' AND a.attnum>0 AND NOT a.attisdropped)x),'constraints',(SELECT json_agg(x ORDER BY table_name,name)FROM(SELECT c.conrelid::regclass::text table_name,c.conname name,c.contype type,c.convalidated validated,c.condeferrable deferrable,c.condeferred deferred,pg_get_constraintdef(c.oid,true) definition FROM pg_constraint c JOIN pg_namespace n ON n.oid=c.connamespace WHERE n.nspname='ops_sso_v1')x),'indexes',(SELECT json_agg(x ORDER BY name)FROM(SELECT c.relname name,pg_get_indexdef(c.oid) definition,i.indisvalid valid,i.indisready ready FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='ops_sso_v1')x),'triggers',(SELECT json_agg(x ORDER BY name)FROM(SELECT t.tgname name,t.tgrelid::regclass::text table_name,t.tgenabled enabled,pg_get_triggerdef(t.oid,true) definition FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='ops_sso_v1' AND NOT t.tgisinternal)x),'functions',(SELECT json_agg(x ORDER BY name)FROM(SELECT p.proname name,p.prosecdef security_definer,p.provolatile volatility,p.proconfig config,l.lanname language,p.prosrc body FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace JOIN pg_language l ON l.oid=p.prolang WHERE n.nspname='ops_sso_v1')x),'relations',(SELECT json_agg(x ORDER BY name)FROM(SELECT c.relname name,c.relkind kind,c.relpersistence persistence,c.relispartition partition,c.relrowsecurity rls,c.relforcerowsecurity force_rls,c.relowner=n.nspowner matching_owner FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='ops_sso_v1')x))`
